async function getFeederList(event, _context, _auth) {
    const { page = 1, pageSize = 10, location, serviceType } = event;
    let whereQuery;
    if (serviceType === 'beauty') {
        const beautyCondition = _.or({ serviceTypes: _.in(['beauty']) }, { serviceTags: _.in(['美容造型']) });
        if (location) {
            whereQuery = _.and({ status: 'active', serviceArea: _.in([location]) }, beautyCondition);
        }
        else {
            whereQuery = _.and({ status: 'active' }, beautyCondition);
        }
    }
    else {
        whereQuery = { status: 'active' };
        if (location) {
            whereQuery.serviceArea = _.in([location]);
        }
        if (serviceType) {
            whereQuery.serviceTypes = _.in([serviceType]);
        }
    }
    const countResult = await db.collection('feeders').where(whereQuery).count();
    const offset = (page - 1) * pageSize;
    const dataResult = await db.collection('feeders')
        .where(whereQuery)
        .field(FEEDER_LIST_FIELDS)
        .orderBy('rating', 'desc')
        .skip(offset)
        .limit(pageSize)
        .get();
    const result = {
        list: (dataResult.data || []),
        total: countResult.total,
        page,
        pageSize,
        totalPages: Math.ceil(countResult.total / pageSize),
        hasNext: page * pageSize < countResult.total,
    };
    return handleSuccess(result, '获取成功');
}
exports.getFeederList = getFeederList;
