exports.handlers = {
    getFeederList,
    getFeederDetail,
    createFeederProfile,
    updateFeederProfile,
    createFeedingOrder,
    getFeedingOrders,
    getOrderStatus,
    updateFeedingOrderStatus,
    getFeederOrders,
    getFeedingOrderDetail,
    handleFeedingOrder,
    getCurrentFeeder,
};
// =====================================================================
// Main 入口
// =====================================================================
async function main(event, context) {
    const { action } = event;
    if (!action || !exports.handlers[action]) {
        throw err('INVALID_PARAMS', '无效的操作类型');
    }
    const AUTH_REQUIRED_ACTIONS = [
        'createFeederProfile', 'updateFeederProfile', 'createFeedingOrder',
        'updateFeedingOrderStatus', 'getFeedingOrders', 'getOrderStatus',
        'getFeederOrders', 'getFeedingOrderDetail', 'handleFeedingOrder', 'getCurrentFeeder',
    ];
    const requireLogin = AUTH_REQUIRED_ACTIONS.includes(action);
    try {
        const auth = await verifyAuth(event, { requireLogin });
        logger.info(action, { openid: auth.openid });
        return await exports.handlers[action](event, context, auth);
    }
    catch (error) {
        logger.error(action, error);
        if (isBusinessError(error)) {
            return toResponse(error);
        }
        const code = error.code || ERROR_CODES.BUSINESS;
        return handleError(error, error.message, code);
    }
}
exports.main = main;
